begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table insight_scope_ids(course_id uuid,secondary_submission uuid,baseline_id uuid,secondary_result uuid,run_id uuid,reservation jsonb);grant select,insert,update on insight_scope_ids to cuevo_api;
insert into app.intelligence_policies(school_id,version,fixture_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',1,true,'20000000-0000-4000-8000-000000000002')on conflict(school_id)do update set fixture_enabled=true,version=1;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Stored insight scope','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)select'10000000-0000-4000-8000-000000000001',('99310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'99300000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Current numeric source '||n,'Teacher authored',10,'61000000-0000-4000-8000-000000000001',2 from generate_series(1,2)n;
insert into app.submissions(school_id,id,assessment_id,learner_id,content)select'10000000-0000-4000-8000-000000000001',('99320000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('99310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000012','Source evidence'from generate_series(1,2)n;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into insight_scope_ids(course_id,secondary_submission,baseline_id,secondary_result)select'99300000-0000-4000-8000-000000000001','99320000-0000-4000-8000-000000000002',internal.release_marking(internal.mark_submission('99320000-0000-4000-8000-000000000001',0,'Teacher reviewed',2,0,true),1,false),internal.release_marking(internal.mark_submission('99320000-0000-4000-8000-000000000002',2,'Teacher reviewed',2,0,true),1,false);
update insight_scope_ids set reservation=internal.begin_teacher_insight_run('insight-scope-golden-001',repeat('a',64),baseline_id,'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1}','insight-scope-request');update insight_scope_ids set run_id=(reservation->>'runId')::uuid;
select lives_ok($$select internal.read_teacher_insight_context((select run_id from insight_scope_ids))$$,'stored source context is disclosed while every source is authorized');
reset role;
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','99330000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000001','New teacher options',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','99340000-0000-4000-8000-000000000001','99330000-0000-4000-8000-000000000001','New lesson',1,'Teacher authored');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','99350000-0000-4000-8000-000000000001','99340000-0000-4000-8000-000000000001','New option','practice','Another allowed learning option',1);
set local role cuevo_api;
select lives_ok($$select internal.read_teacher_insight_context((select run_id from insight_scope_ids))$$,'new authorized context additions do not revoke older saved source access');
select internal.release_marking(internal.mark_submission((select secondary_submission from insight_scope_ids),3,'Correction after run',2,1,true),2,false);
select throws_ok($$select internal.read_teacher_insight_context((select run_id from insight_scope_ids))$$,'42501',null,'secondary source removed from current authority denies historical disclosure');
select throws_ok($$select internal.begin_teacher_insight_run('insight-scope-golden-001',repeat('a',64),(select baseline_id from insight_scope_ids),'{"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1}','insight-scope-replay')$$,'42501',null,'stored source reauthorization precedes original-key replay');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok('select internal.read_intelligence_metrics(30,''FIXTURE'')','42501',null,'metrics do not imply coordinator authority over teacher run contexts');
reset role;
select ok(not has_function_privilege('cuevo_api','internal.require_stored_insight_scope(uuid)','EXECUTE'),'stored context verifier stays private behind governed read/replay');
select*from finish();rollback;
